import{_ as t,o as e,c as a,a2 as u}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"1968年 · 史上最佳战绩","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1968年.md","filePath":"05_quotes/by-year/1968年.md"}'),q={name:"05_quotes/by-year/1968年.md"};function l(r,o,c,p,b,s){return e(),a("div",null,[...o[0]||(o[0]=[u('<h1 id="_1968年-·-史上最佳战绩" tabindex="-1">1968年 · 史上最佳战绩 <a class="header-anchor" href="#_1968年-·-史上最佳战绩" aria-label="Permalink to &quot;1968年 · 史上最佳战绩&quot;">​</a></h1><blockquote><p>&quot;这一结果应当被视为桥牌中摸到十三张黑桃式的异常好运——你叫了满贯，成功了，看起来很低调，赢钱入袋，然后回归正事继续打局牌分。&quot;——巴菲特（37岁）</p></blockquote><p>本页收录1968年致股东信中的经典语录。合伙公司整体收益58.8%，道指仅7.7%——这是历史最高超额收益年份，也是巴菲特在即将解散合伙公司之前，用实力证明&quot;复利奇迹&quot;的最后注脚。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;合伙公司整体收益58.8%，道指整体收益（含全年股息）7.7%。这一结果应当被视为桥牌中摸到十三张黑桃式的异常好运。&quot;</p></blockquote><blockquote><p>&quot;这一结果应当被视为桥牌中摸到十三张黑桃式的异常好运——你叫了满贯，成功了，看起来很低调，赢钱入袋，然后回归正事继续打局牌分。当然，我们的牌也有被吃的时候。&quot;</p></blockquote><blockquote><p>&quot;我们办公室应该挂一块牌匾：&#39;我们不相信奇迹，我们依靠它们。&#39;&quot;</p></blockquote><blockquote><p>&quot;一个代表某机构管理着超过10亿美元共同基金的基金经理宣称：&#39;优秀的基金经理不能仅以周甚至以日为单位来研究证券，必须以分钟为单位来研究证券。&#39;哇！&quot;</p></blockquote><blockquote><p>&quot;有时候看着很有趣，有时候则令人震惊。&quot;</p></blockquote><blockquote><p>&quot;我必须强调，理念的质量和数量目前处于历史最低点。&quot;</p></blockquote><blockquote><p>&quot;一个腿力和击球眼都已衰退的老运动员，偶尔还能挥出一支代打全垒打，但你不会因此改变阵容。&quot;</p></blockquote><blockquote><p>&quot;投资管理行业如今在许多方面已转向极度亢奋。当大量高度积极的人拿着大量资金在有限的合适证券上实践这套时，结果变得高度不可预测。&quot;</p></blockquote><blockquote><p>&quot;曼哈顿基金1968年收益为负6.9%。许多曾经的&#39;go-go&#39;基金如今已被改称为&#39;no-go&#39;基金。&quot;</p></blockquote><blockquote><p>&quot;经过十二年，这四家基金（合计规模远超50亿美元）平均每年仅比道指高出不到一个百分点，这非常耐人寻味。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1968年合伙公司实现58.8%的惊人收益，大幅跑赢道指（7.7%），远超新下调的目标。但巴菲特在信中冷静指出：这就像摸到一手满贯牌，纯属异常好运，理念质量与数量均处于历史最低点。合伙公司净资产已达4400万美元，而合适的投资机会几乎枯竭。这一年，也是巴菲特开始认真考虑结束合伙公司的一年。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1968年/翻译.html">01_letters/1968年/翻译</a> · <a href="/01_letters/1968年/年中信.html">01_letters/1968年/年中信</a></p>',21)])])}const n=t(q,[["render",l]]);export{h as __pageData,n as default};
